; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; DUNEVENT: dungeon events: fountains, the rod, gremlins (941E-964F).
;
; The handlers of the dungeon's event cells, reached from DungeonTurnEnd (DUNMOVE) through the
; table at DungeonEventCmds with BX = the address of the cell (01-08): 1 EventTimeVision, 2 EventFountain,
; 3 EventWind, 4 EventTrap, 5 EventRod, 6 EventGremlins, 8 EventWriting (7 has none). Time
; vision, trap, gremlins and writing clear their cell (they happen once); fountain, wind and rod
; stay. All go back to DungeonLoop. The pictures (TIME, FOUNTAIN, BRAND .IMG) are loaded over
; StartUp as the view buffer, with Location = 4 while one is shown.
; DrawDungeon at the end clears the view and, while a torch burns, calls the DUNGEON.DAT
; overlay at MapBuf (0100) to draw the 3D corridor.
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN Random:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN LoadFile:NEAR
EXTRN DrawView:NEAR
EXTRN Sound:NEAR
EXTRN MapBuf:BYTE
EXTRN MapText:BYTE
EXTRN Location:BYTE
EXTRN PartySize:BYTE
EXTRN Players:BYTE
EXTRN PlayerXY:BYTE
EXTRN LightOn:BYTE
EXTRN DungeonLevel:BYTE
EXTRN StartUp:NEAR
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN ClearView:NEAR
EXTRN Facing:BYTE
EXTRN DexRoll:NEAR
EXTRN MsgStarving:BYTE
EXTRN HurtPlayer:NEAR
EXTRN IsUp:NEAR
EXTRN FlushKeys:NEAR
EXTRN AskPlayer:NEAR
EXTRN StatusLine:NEAR
EXTRN FlashPlayer:NEAR
EXTRN FlashView:NEAR
EXTRN DamageParty:NEAR
EXTRN DungeonLoop:NEAR
EXTRN FileBrandImg:BYTE
EXTRN FileTimeImg:BYTE
EXTRN FileFountainImg:BYTE
EXTRN FountainCmds:BYTE
EXTRN MsgMistyWriting:BYTE
EXTRN MsgTimeVision:BYTE
EXTRN MsgArghTrap:BYTE
EXTRN MsgEvadedTrap:BYTE
EXTRN MsgFountain:BYTE
EXTRN MsgFountainCant:BYTE
EXTRN MsgAhNice:BYTE
EXTRN MsgYuckHorrible:BYTE
EXTRN MsgHowWonderful:BYTE
EXTRN MsgArghBlah:BYTE
EXTRN MsgStrangeWind:BYTE
EXTRN MsgGremlins:BYTE
EXTRN MsgRedHotRod:BYTE
EXTRN MsgLeftMark:BYTE
PUBLIC EventTimeVision
PUBLIC EventFountain
PUBLIC FountainCure
PUBLIC FountainPoison
PUBLIC FountainHeal
PUBLIC FountainHurt
PUBLIC EventWind
PUBLIC EventTrap
PUBLIC EventRod
PUBLIC EventGremlins
PUBLIC EventWriting
PUBLIC DrawDungeon
;------------------------------------------------------------------------------
; EventTimeVision, cell 1: TIME.IMG and "You see a vision of the Time Lord ... Love, Sol,
; Moons & Death, all else fails." (the order of the cards); waits for a key. Cell cleared.
;------------------------------------------------------------------------------
EventTimeVision:	mov byte ptr [bx], 0	; the cell becomes floor: once only	;@941E
	lea bx, StartUp	; load the picture over StartUp	;@9421
	mov cx, 79h	;@9425
	lea dx, FileTimeImg	;@9428
	call LoadFile	;@942C
	call DrawView	; draw the view buffer	;@942F
	mov byte ptr Location, 4	; 4: a picture is shown	;@9432
	lea si, MsgTimeVision	; the Time Lord's words	;@9437
	call PrintMsg	;@943B
	call FlushKeys	;@943E
TimeVision_Wait:	call KeyReady	;@9441
	je TimeVision_Wait	;@9444
	call ReadKey	;@9446
	call ScrollMsg	;@9449
	call DrawDungeon	; back to the 3D view	;@944C
	mov byte ptr Location, 1	; 1: in a dungeon	;@944F
	jmp DungeonLoop	;@9454
;------------------------------------------------------------------------------
; EventFountain, cell 2: FOUNTAIN.IMG, "A fountain. Who will drink?" until Esc. The
; effect depends on the fountain's x & 3 through FountainCmds: 0 poison, 1 heal, 2
; hurt, 3 cure. "Can't!" for a player who is not up. The cell stays.
;------------------------------------------------------------------------------
EventFountain:	lea bx, StartUp	;@9457
	mov cx, 79h	;@945B
	lea dx, FileFountainImg	;@945E
	call LoadFile	;@9462
	call DrawView	;@9465
	mov byte ptr Location, 4	;@9468
	call FlushKeys	;@946D
Fountain_Ask:	lea si, MsgFountain	;@9470
	call PrintMsg	;@9474
	call AskPlayer	; ZF: Esc; else AL = 1-4, BX = record	;@9477
	je Fountain_Done	;@947A
	mov cl, al	; CL = player number 1-4	;@947C
	call IsUp	;@947E
	jne Fountain_Cant	;@9481
	mov al, byte ptr PlayerXY	; the fountain's x ...	;@9483
	and al, 3	; ... & 3 picks the effect	;@9486
	mov ah, 0	;@9488
	shl ax, 1	;@948A
	mov si, ax	;@948C
	jmp word ptr FountainCmds[si]	; FountainCmds	;@948E
Fountain_Cant:	lea si, MsgFountainCant	; "Can't!"	;@9492
	call PrintMsg	;@9496
	mov al, 0FFh	; buzz sound	;@9499
	call Sound	;@949B
	jmp Fountain_Ask	;@949E
Fountain_Done:	mov byte ptr Location, 1	;@94A0
	call DrawDungeon	;@94A5
	jmp DungeonLoop	;@94A8
;------------------------------------------------------------------------------
; FountainCure: "Ah! That's nice!", status Good. BX = record, CL = player 1-4.
;------------------------------------------------------------------------------
FountainCure:	lea si, MsgAhNice	;@94AB
	call PrintMsg	;@94AF
	mov byte ptr [bx+11h], 47h	; status 'G'	;@94B2
	call StatusLine	;@94B6
	jmp Fountain_Ask	;@94B9
;------------------------------------------------------------------------------
; FountainPoison: "Yuck! Horrible!", status Poisoned, flash and hit sound.
;------------------------------------------------------------------------------
FountainPoison:	lea si, MsgYuckHorrible	;@94BB
	call PrintMsg	;@94BF
	mov byte ptr [bx+11h], 50h	; status 'P'	;@94C2
	dec cl	;@94C6
	mov al, cl	;@94C8
	call FlashPlayer	; flash the status line	;@94CA
	mov al, 0F7h	;@94CD
	call Sound	; hit sound	;@94CF
	mov al, cl	;@94D2
	call FlashPlayer	;@94D4
	call StatusLine	;@94D7
	jmp Fountain_Ask	;@94DA
;------------------------------------------------------------------------------
; FountainHeal: "How wonderful!", hit points = maximum.
;------------------------------------------------------------------------------
FountainHeal:	mov ax, word ptr [bx+1Ch]	; max hit points ...	;@94DC
	mov word ptr [bx+1Ah], ax	; ... into the hit points	;@94DF
	lea si, MsgHowWonderful	;@94E2
	call PrintMsg	;@94E6
	call StatusLine	;@94E9
	jmp Fountain_Ask	;@94EC
;------------------------------------------------------------------------------
; FountainHurt: "Argh! Blah! Yuk!", 25 damage, flashes and the hit sound.
;------------------------------------------------------------------------------
FountainHurt:	lea si, MsgArghBlah	;@94EE
	call PrintMsg	;@94F2
	mov al, 25h	; 25 (BCD)	;@94F5
	call HurtPlayer	; subtract from the hit points	;@94F7
	call FlashView	; flash (PARTY 71C1)	;@94FA
	dec cl	;@94FD
	mov al, cl	;@94FF
	call FlashPlayer	;@9501
	mov al, 0F7h	;@9504
	call Sound	; hit sound	;@9506
	mov al, cl	;@9509
	call FlashPlayer	;@950B
	call FlashView	;@950E
	call StatusLine	;@9511
	jmp Fountain_Ask	;@9514
;------------------------------------------------------------------------------
; EventWind, cell 3: "Strange wind!" blows the torch out. The cell stays.
;------------------------------------------------------------------------------
EventWind:	lea si, MsgStrangeWind	;@9517
	call PrintMsg	;@951B
	mov byte ptr LightOn, 0	; the torch is out	;@951E
	call ClearView	;@9523
	jmp DungeonLoop	;@9526
;------------------------------------------------------------------------------
; EventTrap, cell 4: "Argh!! A trap!!"; only the first player's dexterity is checked
; (ITEMS 5B85): "Evaded!!" or the whole party is hurt (DamageParty). Cell cleared.
;------------------------------------------------------------------------------
EventTrap:	mov byte ptr [bx], 0	; the cell becomes floor	;@9529
	lea si, MsgArghTrap	;@952C
	call PrintMsg	;@9530
	mov al, 0F6h	; tick sound	;@9533
	call Sound	;@9535
	lea bx, Players	; always player 1	;@9538
	call DexRoll	; ZF set: evaded	;@953C
	jne Trap_Hit	;@953F
	lea si, MsgEvadedTrap	; "Evaded!!"	;@9541
	call PrintMsg	;@9545
	jmp short Trap_Done	;@9548
Trap_Hit:	call DamageParty	; DamageParty	;@954A
Trap_Done:	jmp DungeonLoop	;@954D
;------------------------------------------------------------------------------
; EventRod, cell 5: BRAND.IMG, "A red hot rod in the wall. Who will touch?" The player
; chosen gets the mark bit 1 << (4 + (x & 3)) in record offset 0Eh (so the rod's x picks the
; mark) and 50 damage: "It left a mark!". The cell stays.
;------------------------------------------------------------------------------
EventRod:	lea bx, StartUp	;@9550
	mov cx, 79h	;@9554
	lea dx, FileBrandImg	;@9557
	call LoadFile	;@955B
	call DrawView	;@955E
	mov byte ptr Location, 4	;@9561
	lea si, MsgRedHotRod	;@9566
	call PrintMsg	;@956A
	call FlushKeys	;@956D
	call AskPlayer	; ZF: Esc; else AL = 1-4, BX = record	;@9570
	je Rod_Done	;@9573
	mov ah, byte ptr PlayerXY	; the rod's x ...	;@9575
	and ah, 3	;@9579
	mov cl, ah	;@957C
	add cl, 4	; ... & 3 + 4: bit 4-7	;@957E
	mov ah, 1	;@9581
	shl ah, cl	;@9583
	or byte ptr [bx+0Eh], ah	; marks (record 0Eh, bits 7-4)	;@9585
	dec al	;@9588
	call FlashPlayer	; flash the status line	;@958A
	mov ah, al	;@958D
	mov al, 0F7h	;@958F
	call Sound	; hit sound	;@9591
	mov al, ah	;@9594
	call FlashPlayer	;@9596
	mov al, 50h	; 50 (BCD) damage	;@9599
	call HurtPlayer	;@959B
	call StatusLine	;@959E
	lea si, MsgLeftMark	; "It left a mark!"	;@95A1
	call PrintMsg	;@95A5
Rod_Done:	mov byte ptr Location, 1	;@95A8
	call DrawDungeon	;@95AD
	jmp DungeonLoop	;@95B0
;------------------------------------------------------------------------------
; EventGremlins, cell 6: a random player, if up, "Gremlins!": the food word (record
; 21h-22h, BCD) loses 1 in its high byte, i.e. 100 food. With less than 100 the food becomes
; 0, "Starving!" and 5 damage. Cell cleared.
;------------------------------------------------------------------------------
EventGremlins:	mov byte ptr [bx], 0	; the cell becomes floor	;@95B3
	mov dh, byte ptr PartySize	;@95B6
	call Random	; DL = a player 0 .. PartySize-1	;@95BA
	mov al, 40h	;@95BD
	mul dl	;@95BF
	mov bx, ax	;@95C1
	lea bx, Players[bx]	; BX = his record	;@95C3
	call IsUp	;@95C7
	jne Gremlins_Done	;@95CA
	lea si, MsgGremlins	; "Gremlins!"	;@95CC
	call PrintMsg	;@95D0
	mov ax, word ptr [bx+21h]	; food (BCD word 21h-22h)	;@95D3
	xchg al, ah	; the high byte: hundreds	;@95D6
	sub al, 1	; 100 food less	;@95D8
	das	;@95DA
	xchg al, ah	;@95DB
	mov word ptr [bx+21h], ax	;@95DD
	jae Gremlins_Done	; no borrow: done	;@95E0
	mov word ptr [bx+21h], 0	; less than 100: no food at all	;@95E2
	lea si, MsgStarving	; "Starving!"	;@95E7
	call PrintMsg	;@95EB
	mov al, dl	;@95EE
	call FlashPlayer	; flash the status line	;@95F0
	mov al, 0F7h	;@95F3
	call Sound	; hit sound	;@95F5
	mov al, dl	;@95F8
	call FlashPlayer	;@95FA
	mov al, 5	; 5 (BCD) damage	;@95FD
	call HurtPlayer	;@95FF
Gremlins_Done:	call StatusLine	;@9602
	mov al, 0FAh	; rise sound	;@9605
	call Sound	;@9607
	jmp DungeonLoop	;@960A
;------------------------------------------------------------------------------
; EventWriting, cell 8: "Misty writing:" and this level's message from the dungeon
; file (MapText at 1100: a word offset per level). Cell cleared.
;------------------------------------------------------------------------------
EventWriting:	mov byte ptr [bx], 0	; the cell becomes floor	;@960D
	lea si, MsgMistyWriting	; "Misty writing:"	;@9610
	call PrintMsg	;@9614
	mov bl, byte ptr DungeonLevel	;@9617
	mov bh, 0	;@961B
	shl bx, 1	;@961D
	mov si, word ptr MapText[bx]	; offset of this level's message	;@961F
	lea si, MapText[si]	;@9623
	call PrintMsg	;@9627
	call ScrollMsg	;@962A
	jmp DungeonLoop	;@962D
;------------------------------------------------------------------------------
; DrawDungeon: clear the view; while a torch burns call the DUNGEON.DAT overlay at
; MapBuf (0100) with AL = Facing, AH = DungeonLevel, BX = PlayerXY (x, y): it draws the 3D
; corridor (docs/FORMATS.md 8). Saves flags, AX, BX.
;------------------------------------------------------------------------------
DrawDungeon:	pushf	;@9630
	push ax	;@9631
	push bx	;@9632
	call ClearView	;@9633
	cmp byte ptr LightOn, 0	; no torch: nothing to see	;@9636
	je DrawDungeon_Done	;@963B
	mov al, byte ptr Facing	;@963D
	mov ah, byte ptr DungeonLevel	;@9640
	mov bx, word ptr PlayerXY	;@9644
	call near ptr MapBuf	; the overlay's entry: jmp to its code at 0447	;@9648
DrawDungeon_Done:	pop bx	;@964B
	pop ax	;@964C
	popf	;@964D
	ret	;@964E
CODE ENDS
END
